do $$
declare
  v_doc_id uuid;
  v_item record;
begin
  select id into v_doc_id from public.regulation_documents
   where document_code='DP-SR-HR-001' and revision='003' and is_shared_standard=true
   order by created_at desc limit 1;
  if v_doc_id is null then
    insert into public.regulation_documents
      (company_id,title,document_code,revision,effective_date,original_file_name,file_sha256,source_status,is_shared_standard)
    values
      ('3242719e-4cd2-44d5-8943-60e7fc1fb267',
       'ข้อบังคับเกี่ยวกับการทำงาน – หมวด 10 วินัยและโทษทางวินัย',
       'DP-SR-HR-001','003','2026-07-06','หมวดที่ 10(1).pdf',
       'ad6e461d111efd3a0ae116ce4c1f99c0bfce8f57f50211d9e9f4c11e060f04e7',
       'indexed','true')
    returning id into v_doc_id;
  end if;
  for v_item in select * from jsonb_to_recordset($clauses$[{"section_number":"10.2.1","content_text":"การไม่มาปฏิบัติงานตามตารางโดยไม่มีเหตุผลอันสมควร ถือเป็นการขาดงาน","source_page":1,"sort_order":1},{"section_number":"10.2.2","content_text":"บริษัทมีสิทธิพิจารณาดำเนินการทางวินัยตามข้อบังคับของบริษัท","source_page":1,"sort_order":2},{"section_number":"10.2.3","content_text":"บริษัทจะพิจารณาความเหมาะสม ความจำเป็น และเหตุผลของพนักงานเป็นรายกรณี","source_page":1,"sort_order":3},{"section_number":"10.2.4","content_text":"มาทำงานสายหรือกลับก่อนเวลาที่กำหนดไว้ โดยไม่ได้รับอนุญาตจากผู้บังคับบัญชา","source_page":1,"sort_order":4},{"section_number":"10.2.5","content_text":"นอนหรือหลับในระหว่างปฏิบัติหน้าที่หรือนำงานอื่นที่ไม่ใช่งานของบริษัทมาทำในเวลาปฏิบัติหน้าที่","source_page":1,"sort_order":5},{"section_number":"10.2.6","content_text":"ขาดงานโดยไม่มีเหตุอันสมควรหรือหยุดงานโดยไม่ได้รับอนุญาต","source_page":1,"sort_order":6},{"section_number":"10.2.7","content_text":"ออกนอกบริเวณบริษัทระหว่างเวลางาน เว้นแต่ได้รับอนุญาตจากผู้บังคับบัญชา","source_page":1,"sort_order":7},{"section_number":"10.2.8","content_text":"แสดงกริยาหรือวาจาหยาบคาย ก้าวร้าว ดูหมิ่น ล่วงเกิน เหยียดหยามบุคคลภายนอกผู้มาติดต่องานกับบริษัท รวมถึงผู้บังคับบัญชา และ/หรือพนักงานด้วยกัน","source_page":1,"sort_order":8},{"section_number":"10.2.9","content_text":"มีเจตนาทุจริต หรือแก้ไขเอกสารใด ๆ ที่มีผลต่อการจ่ายค่าตอบแทน","source_page":1,"sort_order":9},{"section_number":"10.2.10","content_text":"ละทิ้ง หลีกเลี่ยง ละเลย หน่วงเหนี่ยวงานโดยไม่มีเหตุอันสมควร","source_page":1,"sort_order":10},{"section_number":"10.2.11","content_text":"เสพสุรา หรือสิ่งมึนเมา หรือยาเสพติดให้โทษทุกชนิด หรือนำสิ่งของดังกล่าวเข้ามาในบริเวณสถานที่ทำงานของบริษัท หรือเข้ามาในสถานที่ทำงานในลักษณะมึนเมา","source_page":1,"sort_order":11},{"section_number":"10.2.12","content_text":"นำสิ่งของผิดกฎหมายเข้ามาในบริเวณบริษัท","source_page":1,"sort_order":12},{"section_number":"10.2.13","content_text":"นำสิ่งของ อุปกรณ์ เครื่องมือ เครื่องใช้ หรือผลิตภัณฑ์ของบริษัทไปใช้ในกิจการส่วนตัว หรือนำออกนอกที่ทำการบริษัทโดยไม่ได้รับอนุญาต","source_page":1,"sort_order":13},{"section_number":"10.2.14","content_text":"ฝ่าฝืนหรือไม่ปฏิบัติตามกฎ ข้อบังคับ ระเบียบ ประกาศ คำสั่งของบริษัท หรือของผู้บังคับบัญชาที่ชอบด้วยหน้าที่และกฎหมาย","source_page":1,"sort_order":14},{"section_number":"10.2.15","content_text":"ปกป้อง หรือไม่ลงโทษผู้ใต้บังคับบัญชา เมื่อผู้ใต้บังคับบัญชาทำผิดวินัย","source_page":1,"sort_order":15},{"section_number":"10.2.16","content_text":"เจตนายุแหย่ แพร่ข่าวอกุศล เพื่อก่อให้เกิดความแตกแยกในหมู่พนักงาน","source_page":1,"sort_order":16},{"section_number":"10.2.17","content_text":"ทะเลาะวิวาท หรือยั่วยุ หรือท้าทายให้เกิดการต่อสู้","source_page":1,"sort_order":17},{"section_number":"10.2.18","content_text":"ทำร้ายร่างกายซึ่งกันและกัน หรือทำร้ายบุคคลอื่นในสถานที่ทำงาน หรือในบริเวณบริษัท","source_page":1,"sort_order":18},{"section_number":"10.2.19","content_text":"ให้ถ้อยคำ หรือข้อความอันเป็นเท็จต่อผู้บังคับบัญชา","source_page":1,"sort_order":19},{"section_number":"10.2.20","content_text":"เล่นการพนันในสถานที่ทำงาน หรือในบริเวณบริษัท","source_page":1,"sort_order":20},{"section_number":"10.2.21","content_text":"ข่มขู่ หรือใช้อำนาจหน้าที่บังคับหรือแสดงอิทธิพลใด ๆ ให้พนักงานอื่นเกิดความเกรงกลัว เพื่อประโยชน์ส่วนตัวหรือของผู้อื่น","source_page":1,"sort_order":21},{"section_number":"10.2.22","content_text":"แสดงนิสัย หรือความประพฤติ หรือแสดงตนเป็นอันธพาล","source_page":1,"sort_order":22},{"section_number":"10.2.23","content_text":"ทำลาย ต่อเติมหรือแก้ไขข้อความในประกาศหรือคำสั่งหรือระเบียบข้อบังคับของบริษัท","source_page":1,"sort_order":23},{"section_number":"10.2.24","content_text":"พกพา หรือนำอาวุธ หรือวัตถุระเบิดใด ๆ เข้ามาในสถานที่ทำงานโดยไม่ได้รับอนุญาตเป็นลายลักษณ์อักษรจากผู้บังคับบัญชาโดยตรง","source_page":2,"sort_order":24},{"section_number":"10.2.25","content_text":"เจตนาทำลายชื่อเสียง และความเชื่อถือของบริษัทในทุกกรณี","source_page":2,"sort_order":25},{"section_number":"10.2.26","content_text":"เจตนาทำลายให้เกิดความเสียหายแก่เครื่องมือ เครื่องใช้ อุปกรณ์ ทรัพย์สินของบริษัท","source_page":2,"sort_order":26},{"section_number":"10.2.27","content_text":"รับสินบนจากผู้อื่น หรือแสวงหาผลกำไรจากบริษัทโดยมิชอบ","source_page":2,"sort_order":27},{"section_number":"10.2.28","content_text":"การใช้อำนาจสั่งผู้ใต้บังคับบัญชาทำงานให้ตนเองเป็นส่วนตัวในระหว่างเวลางาน","source_page":2,"sort_order":28},{"section_number":"10.2.29","content_text":"ก้าวก่ายการปฏิบัติหน้าที่ของผู้อื่น หรือเข้าไปในเขตปฏิบัติงานที่ตนไม่มีหน้าที่เกี่ยวข้อง","source_page":2,"sort_order":29},{"section_number":"10.2.30","content_text":"เปิดเผยความลับของบริษัท หมายถึง เทคนิค วิธีการทางวิชาชีพของบริษัท และความลับอื่น ๆ ทั้งหมด","source_page":2,"sort_order":30},{"section_number":"10.2.31","content_text":"แก้ไข ปลอมแปลงเอกสารของบริษัท","source_page":2,"sort_order":31},{"section_number":"10.2.32","content_text":"ไม่ติดบัตรพนักงานตามที่กำหนดในขณะปฏิบัติหน้าที่","source_page":2,"sort_order":32},{"section_number":"10.2.33","content_text":"นำบุคคลภายนอกซึ่งไม่มีส่วนเกี่ยวข้องกับบริษัทเข้ามาในบริษัทโดยไม่มีเหตุอันสมควร หรือไม่ได้รับอนุญาตจากผู้บังคับบัญชาหรือฝ่ายบริหารทรัพยากรบุคคล","source_page":2,"sort_order":33},{"section_number":"10.2.34","content_text":"การกระทำใด ๆ หรือก่อตัวดำเนินงาน หรือเข้ามีส่วนร่วมในการบริหารงานในนามของบุคคล โดยไม่ได้รับอนุญาตจากผู้บังคับบัญชา","source_page":2,"sort_order":34},{"section_number":"10.2.35","content_text":"ไม่ปฏิบัติตามกฎแห่งความปลอดภัยในการทำงาน","source_page":2,"sort_order":35},{"section_number":"10.2.36","content_text":"ละเลยการปฏิบัติหน้าที่ตามข้อกำหนด กฎหมายที่เกี่ยวข้องในหน้าที่งานที่รับผิดชอบ","source_page":2,"sort_order":36},{"section_number":"10.2.37","content_text":"สูบบุหรี่ในบริเวณที่ห้ามสูบ","source_page":2,"sort_order":37},{"section_number":"10.2.38","content_text":"ก่อกวนความสงบสุขของผู้พักอาศัยในอาคารบ้านพักของบริษัท","source_page":2,"sort_order":38},{"section_number":"10.2.39","content_text":"ไม่รักษาความสะอาดสำนักงาน บริเวณโกดังและบ้านพักของบริษัท","source_page":2,"sort_order":39},{"section_number":"10.2.40","content_text":"ทำการเรี่ยไรใด ๆ ในสถานที่ของบริษัทหรือบริเวณโกดังโดยไม่ได้รับอนุญาต","source_page":2,"sort_order":40},{"section_number":"10.2.41","content_text":"การไม่ปฏิบัติตามกฎหมายว่าด้วยการคุ้มครองข้อมูลส่วนบุคคล","source_page":2,"sort_order":41},{"section_number":"10.2.41.1","content_text":"เปิดเผยข้อมูลส่วนบุคคลของผู้อื่นโดยไม่ได้รับความยินยอมหรือไม่มีฐานทางกฎหมายที่ใช้ในการอ้างอิงการใช้หรือเปิดเผยข้อมูลส่วนบุคคลนั้น","source_page":2,"sort_order":42},{"section_number":"10.2.41.2","content_text":"เปิดเผยข้อมูลส่วนบุคคลของบุคคลอื่นนอกวัตถุประสงค์ที่บริษัทได้แจ้งให้กับเจ้าของข้อมูลส่วนบุคคลนั้นรับทราบ","source_page":2,"sort_order":43},{"section_number":"10.2.41.3","content_text":"เปิดเผยข้อมูลส่วนบุคคลอันเป็นข้อมูลอ่อนไหว หรือข้อมูลทั่วไปอันอาจเป็นเหตุให้เกิดความเสียหาย โดยเฉพาะเพื่อแสวงหาประโยชน์ที่ไม่ควรได้ต่อตนเองหรือบุคคลภายนอก และไม่ว่าจะส่งหรือโอนภายในประเทศหรือต่างประเทศ","source_page":2,"sort_order":44},{"section_number":"10.2.42","content_text":"กระทำการใด ๆ นอกไปจากที่กล่าวข้างต้น หากโดยธรรมเนียมหรือจารีตประเพณี หรือโดยสามัญสำนึกของบุคคลทั่วไปถือว่าเป็นความผิดแล้ว ให้ถือว่าการกระทำนั้น ๆ เป็นความผิดทางวินัย","source_page":2,"sort_order":45}]$clauses$::jsonb)
    as x(section_number text, content_text text, source_page integer, sort_order integer)
  loop
    if not exists(select 1 from public.regulation_sections where document_id=v_doc_id and section_number=v_item.section_number) then
      insert into public.regulation_sections
        (document_id,company_id,category_code,section_number,heading,content_text,source_page,sort_order)
      values
        (v_doc_id,'3242719e-4cd2-44d5-8943-60e7fc1fb267','discipline',
         v_item.section_number,'ข้อ '||v_item.section_number,v_item.content_text,v_item.source_page,v_item.sort_order);
    end if;
  end loop;
end $$;